css:
.loader{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 3.7);
  position:relative;
  display:inline-block;
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
  animation:td-flash var(--loader-speed, 1s) infinite linear alternate;animation-delay:calc(var(--loader-speed, 1s) / 2);
}
.loader::before,
.loader::after{
  content:"";
  position:absolute;
  top:0;
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:inherit;
}
.loader::before{left:calc(var(--td-gap) * -1);}
.loader::after{left:var(--td-gap);}
.loader::before{animation:td-flash var(--loader-speed, 1s) infinite linear alternate;animation-delay:0s;background-color:var(--loader-color, #6366f1)}
.loader::after{animation:td-flash var(--loader-speed, 1s) infinite linear alternate;animation-delay:var(--loader-speed, 1s);background-color:var(--loader-color, #6366f1)}
@keyframes td-flash{
  0%{background-color:var(--loader-color, #6366f1)}
  50%,100%{background-color:var(--loader-secondary-color, #a5b4fc)}
}
